  ('The Turin Horse', 2011, 'Béla Tarr, Ágnes Hranitzky', 155, 7.7, 'drama', ARRAY['heavy', 'cerebral']::text[], ARRAY[]::text[], 'A farmer and his daughter on a windswept plain endure six days as their horse refuses to move and the world slowly fades.'),
  ('Mustang', 2015, 'Deniz Gamze Ergüven', 97, 7.6, 'drama', ARRAY['inspiring', 'heavy']::text[], ARRAY[]::text[], 'Five orphaned sisters in a Turkish village fight back as their family locks them up and marries them off one by one.'),
  ('Satantango', 1994, 'Béla Tarr', 439, 8.2, 'drama', ARRAY['cerebral', 'heavy']::text[], ARRAY[]::text[], 'In a dying Hungarian collective farm, villagers hear that a charismatic man they thought was dead is coming back.'),
  ('The Handmaiden', 2016, 'Park Chan-wook', 145, 8.1, 'romance', ARRAY['romantic', 'mind-bending']::text[], ARRAY[]::text[], 'In 1930s Korea, a con man hires a pickpocket as a maid to help him seduce a Japanese heiress out of her fortune.'),
  ('Come and See', 1985, 'Elem Klimov', 142, 8.3, 'thriller', ARRAY['heavy']::text[], ARRAY[]::text[], 'A Belarusian boy joins the partisans during the Nazi occupation and witnesses the horrors of the war firsthand.'),
  ('Another Round', 2020, 'Thomas Vinterberg', 117, 7.7, 'comedy', ARRAY['funny', 'tearjerker']::text[], ARRAY[]::text[], 'Four bored high school teachers test a theory that life is better with a little alcohol in your blood at all times.'),
  ('The Father', 2020, 'Florian Zeller', 97, 8.2, 'thriller', ARRAY['tearjerker', 'mind-bending']::text[], ARRAY[]::text[], 'An elderly man with dementia refuses his daughter''s help, and his world shifts in confusing ways around him.'),
  ('The Conjuring', 2013, 'James Wan', 112, 7.5, 'horror', ARRAY['scary']::text[], ARRAY[]::text[], 'Paranormal investigators Ed and Lorraine Warren help a family terrorized by a dark presence in their Rhode Island farmhouse.'),
  ('The Conjuring 2', 2016, 'James Wan', 134, 7.3, 'horror', ARRAY['scary']::text[], ARRAY[]::text[], 'The Warrens travel to London to help a single mother whose house in Enfield is plagued by a malicious spirit.'),
  ('Sound of Metal', 2019, 'Darius Marder', 120, 7.7, 'biography', ARRAY['heavy', 'inspiring']::text[], ARRAY[]::text[], 'A heavy-metal drummer starts losing his hearing and has to decide who he is without it.'),
  ('I''m Thinking of Ending Things', 2020, 'Charlie Kaufman', 134, 6.5, 'thriller', ARRAY['mind-bending', 'dark']::text[], ARRAY[]::text[], 'A young woman drives through a snowstorm to meet her boyfriend''s parents, while thinking about ending the relationship.'),
  ('Anomalisa', 2015, 'Duke Johnson, Charlie Kaufman', 90, 7.2, 'animation', ARRAY['quirky', 'heavy']::text[], ARRAY[]::text[], 'A lonely customer-service author who hears everyone in the same voice meets one woman who sounds different.'),
  ('The Lighthouse', 2019, 'Robert Eggers', 109, 7.3, 'fantasy', ARRAY['mind-bending', 'scary']::text[], ARRAY[]::text[], 'Two lighthouse keepers on a remote New England island in the 1890s slowly lose their grip on sanity.'),
  ('The Killing of a Sacred Deer', 2017, 'Yorgos Lanthimos', 121, 7.0, 'horror', ARRAY['dark', 'scary']::text[], ARRAY[]::text[], 'A successful surgeon takes a strange teenage boy under his wing, and the boy''s demands become impossible.'),
  ('Marriage Story', 2019, 'Noah Baumbach', 137, 7.9, 'romance', ARRAY['tearjerker', 'heavy']::text[], ARRAY[]::text[], 'A stage director and his actor wife try to divorce kindly, until the lawyers and a cross-country custody fight take over.'),
  ('Mank', 2020, 'David Fincher', 131, 6.8, 'biography', ARRAY['cerebral', 'nostalgic']::text[], ARRAY[]::text[], 'A hard-drinking screenwriter races to finish the script for Citizen Kane, in 1940s Hollywood shot in black and white.'),
  ('The Florida Project', 2017, 'Sean Baker', 111, 7.6, 'drama', ARRAY['heartwarming', 'heavy']::text[], ARRAY[]::text[], 'A six-year-old spends her summer running wild around a cheap motel near Disney World, while her mother struggles to pay rent.');
